pub type LogLevel = enum {
  Info,
  Warning,
  Error,
} derive[Eq]

fn is_critical(level: &LogLevel) -> Bool {
  return level == &LogLevel.Error;
}

fn main() -> Int {
  let l1 = LogLevel.Info;
  let l2 = LogLevel.Warning;
  let l3 = LogLevel.Error;
  var count = 0;
  if is_critical(&l1) { count = count + 1; }
  if is_critical(&l2) { count = count + 1; }
  if is_critical(&l3) { count = count + 1; }
  return count;
}
